CREATE TABLE IF NOT EXISTS security_event(seq_no BIGINT PRIMARY KEY,event_time VARCHAR(40) NOT NULL,source_ip VARCHAR(45) NOT NULL,username VARCHAR(128),endpoint VARCHAR(255),http_method VARCHAR(10),user_agent VARCHAR(512),risk_score INT NOT NULL,risk_level VARCHAR(8) NOT NULL,rules_hit VARCHAR(255),prev_hash CHAR(64) NOT NULL,chain_hash CHAR(64) NOT NULL,sent_status VARCHAR(12) DEFAULT 'PENDING');
CREATE TABLE IF NOT EXISTS integrity_epoch(node_id VARCHAR(64) NOT NULL,epoch_no BIGINT NOT NULL,first_seq BIGINT NOT NULL,last_seq BIGINT NOT NULL,chain_head CHAR(64) NOT NULL,seal_tag CHAR(64),sealed_at_ms BIGINT NOT NULL,checkpoint_timestamp BIGINT,checkpoint_signature BLOB,PRIMARY KEY(node_id,epoch_no),UNIQUE KEY uq_integrity_epoch_last_seq(node_id,last_seq));
CREATE TABLE IF NOT EXISTS integrity_stream_state(node_id VARCHAR(64) PRIMARY KEY,encrypted_state BLOB NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
